      // Downdetector / service status page
      downdetector_hero_eyebrow: 'Status de serviços em tempo real',
      downdetector_hero_title: 'Está fora do ar para todo mundo ou só para você?',
      downdetector_hero_subtitle: 'Status operacional ao vivo + histórico de incidentes das últimas 24 horas para mais de 50 serviços populares. Pesquise qualquer serviço: os conhecidos abrem aqui, os desconhecidos vão para o Downdetector.',
      downdetector_search_label: 'Nome do serviço ou URL',
